mapper.select:
select sp.customer_id, s.name as customerName, sp.so_org_id as SoOrgId, sp.so_org_name as SoOrgName, spd.currency, spd.tax_price as taxPrice, spd.tax_rate * 100 as taxRate, spd.min_qty as minQty, spd.max_qty as maxQty from so_price sp inner join so_price_detail spd on sp.id = spd.main_id and spd.is_deleted = false inner join customer_info s on sp.customer_id = s.id and s.is_deleted = false
sp.is_deleted = false and sp.approve_status = 'approve' and spd.disabled = false and to_char(now(), 'yyyy-mm-dd')::TIMESTAMP >= spd.effective_date and spd.expire_date >= to_char(now(), 'yyyy-mm-dd')::TIMESTAMP
and spd.sku_id = #{params.skuId}
and spd.max_qty > #{params.soQty} and #{params.soQty} >= spd.min_qty
and sp.customer_id = #{params.customerId}
and sp.so_org_id = #{params.SoOrgId}

SELECT id, sku_id, min_qty, max_qty, currency, tax_price, tax_rate, effective_date, expire_date, disabled FROM so_price_detail WHERE is_deleted = false AND main_id IN ( SELECT id FROM so_price WHERE customer_id = #{customerId} AND so_org_id = #{SoOrgId} AND is_deleted=FALSE
AND approve_status IN
#{status}
)
AND sku_id IN
#{skuId}

SELECT spd.id, spd.sku_id, spd.delivery_day, spd.min_qty, spd.max_qty, spd.currency, spd.tax_price, spd.tax_rate, spd.disabled, sp.approve_status FROM so_price_detail spd inner join so_price sp on sp.id = spd.main_id WHERE spd.is_deleted=FALSE AND sp.is_deleted=FALSE and sp.customer_id = #{customerId} and sp.so_org_id = #{soOrgId}
AND sp.approve_status IN
#{status}

SELECT spd.id, spd.create_user_id, spd.create_user_name, spd.create_time, spd.update_user_id, spd.update_user_name, spd.update_time, spd.version, spd.is_deleted, spd.sku_id, spd.main_id, spd.sku_no, spd.min_qty, spd.max_qty, spd.currency, spd.tax_price, spd.expire_date, spd.tax_rate, spd.effective_date, spd.disabled, spd.remark, sp.approve_status, sp.customer_id, sp.code AS priceCode, sp.so_org_name FROM so_price_detail spd inner join so_price sp on sp.id = spd.main_id AND spd.is_deleted = FALSE WHERE sp.is_deleted = FALSE
AND spd.id IN
#{item}
